function getInventoryColumn(header) {
  const normalizedHeader = normalizeHeader(header).toLowerCase();
  const exactMatch = Object.entries(HEADER_ALIASES).find(([, aliases]) =>
    aliases.includes(normalizedHeader),
  );
  if (exactMatch) return exactMatch[0];

  return Object.entries(HEADER_ALIASES).find(([, aliases]) =>
    aliases.some(
      (alias) =>
        normalizedHeader.includes(alias) || alias.includes(normalizedHeader),
    ),
  )?.[0];
}

router.post('/save', async (req, res) => {
  const { userId, plantData } = req.body;
  if (!userId || !plantData) {
    return res.status(400).json({ error: 'userId and plantData required' });
  }
  const exists = await UserPlant.findOne({
    firebaseUid: userId,
    trefleId: plantData.id
  });
  if (exists) {
    return res.status(409).json({ error: 'Plant already saved', plant: exists });
  }
  const plant = await UserPlant.create({
    firebaseUid: userId,
    trefleId: plantData.id,
    commonName: plantData.common_name,
    scientificName: plantData.scientific_name
  });
  res.status(201).json({ message: 'Plant saved', plant });
});

async function generateCodeChallenge(codeVerifier) {
  const hash = crypto.createHash("sha256");
  hash.update(codeVerifier);
  const digest = hash.digest();
  return digest
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

function update() {
    if (gameOver) return;
    requestAnimationFrame(update);
    context.clearRect(0, 0, board.width, board.height);

    velocityY += gravity;
    dino.y = Math.min(dino.y + velocityY, 156);
    context.drawImage(dinoImg, dino.x, dino.y, dino.width, dino.height);

    cactusArray.forEach(cactus => {
        cactus.x += velocityX;
        context.drawImage(cactus.img, cactus.x, cactus.y, cactus.width, cactus.height);
